/* Web presentation materials derive from the existing prototype SSOT; no second brand palette. */
:root {
 --web-glass:color-mix(in oklch,var(--surface-deep) 88%,transparent);
 --web-bar:color-mix(in oklch,var(--sidebar) 94%,transparent);
 --web-soft-glass:color-mix(in oklch,var(--background) 67%,transparent);
 --web-line:color-mix(in oklch,var(--cyan) 24%,var(--border));
 --web-window-shadow:0 15px 45px color-mix(in oklch,var(--background) 65%,transparent);
 --web-wallpaper-overlay:linear-gradient(180deg,color-mix(in oklch,var(--background) 15%,transparent),color-mix(in oklch,var(--background) 10%,transparent) 40%,color-mix(in oklch,var(--background) 45%,transparent));
 --web-blue-icon:linear-gradient(150deg,color-mix(in oklch,var(--cyan) 65%,var(--primary)),var(--primary));
 --web-violet-icon:linear-gradient(145deg,var(--violet),color-mix(in oklch,var(--primary) 65%,var(--background)));
 --web-cyan-icon:linear-gradient(145deg,var(--cyan),color-mix(in oklch,var(--primary) 80%,var(--background)));
 --web-mint-icon:linear-gradient(145deg,var(--mint),color-mix(in oklch,var(--mint) 40%,var(--background)));
}
.web-workspace{--web-sidebar-width:190px;--web-header-height:62px;--web-footer-height:66px;position:relative;height:100dvh;min-height:0;isolation:isolate;overflow:hidden;font-size:12px;background:var(--background)}
.web-wallpaper,.web-wallpaper-shade{position:absolute;inset:0;height:100%;width:100%;object-fit:cover;z-index:-2}.web-wallpaper{object-position:center}.web-wallpaper-shade{background:var(--web-wallpaper-overlay);z-index:-1}.web-compact{--web-sidebar-width:68px}.web-skip{position:absolute;left:200px;top:-100px;z-index:100;background:var(--card);padding:12px}.web-skip:focus{top:5px}
.web-topbar{position:absolute;inset:0 0 auto;height:var(--web-header-height);z-index:50;display:grid;grid-template-columns:var(--web-sidebar-width) minmax(0,1fr) auto;align-items:center;background:var(--web-bar);backdrop-filter:blur(22px);border-bottom:1px solid var(--border);gap:25px;padding-right:20px}
.web-brand{display:flex;align-items:center;gap:8px;padding-left:19px;font:500 21px var(--font-display);min-width:0}.web-brand img{width:30px;height:30px;object-fit:contain;flex-shrink:0}.web-brand small{font:500 8px var(--font-sans);border:1px solid var(--border);border-radius:4px;padding:2px 4px;color:var(--muted-foreground)}
.web-global-search{height:35px;max-width:530px;width:100%;justify-self:center;background:var(--web-soft-glass);font-size:10px;color:var(--muted-foreground);padding:0 13px;justify-content:start;min-width:0}.web-global-search>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}.web-global-search kbd{margin-left:auto;border:1px solid var(--border);padding:1px 4px;border-radius:3px;font-size:8px;flex-shrink:0}.web-header-actions{display:flex;align-items:center;gap:6px}.web-header-actions>button{color:var(--muted-foreground)}.web-header-divider{height:22px;width:1px;background:var(--border);margin:0 7px}.web-identity{padding:0;gap:9px;text-align:left}.web-identity>span:nth-child(2){display:flex;flex-direction:column;gap:3px}.web-identity strong{font-size:10px;font-weight:500}.web-identity small{font-size:8px;color:var(--muted-foreground)}.web-user-symbol{width:29px;height:29px;border:1px solid var(--border);background:var(--accent);border-radius:50%;display:grid;place-items:center;color:var(--cyan)}.web-identity>svg{width:11px}.web-user-symbol svg{width:16px}
.web-navigation-content{display:flex;flex:1;flex-direction:column;min-height:0}.web-sidebar{position:absolute;left:0;top:var(--web-header-height);bottom:var(--web-footer-height);width:var(--web-sidebar-width);background:var(--web-bar);backdrop-filter:blur(22px);border-right:1px solid var(--border);padding:14px 11px;display:flex;flex-direction:column;z-index:40}.web-sidebar-label{display:flex;align-items:center;justify-content:space-between;padding-left:10px;color:var(--subtle);margin-bottom:10px}.web-sidebar-label>span{font-size:8px}.web-sidebar-label button{height:25px;width:25px}.web-sidebar-label svg{width:13px}.web-nav-link{width:100%;justify-content:start;gap:11px;font-size:11px;font-weight:400;padding:0 12px;min-height:39px;margin-bottom:4px;color:var(--muted-foreground);border:1px solid transparent}.web-nav-link.selected{background:var(--active-gradient);color:var(--foreground);border-color:var(--border);box-shadow:inset 2px 0 var(--cyan)}.web-nav-link.selected svg{color:var(--cyan)}.web-nav-link svg{width:17px;height:17px}.web-sidebar-favorites{border-top:1px solid var(--border);padding-top:17px;margin-top:17px}.web-sidebar-favorites>span{display:block;font-size:9px;color:var(--muted-foreground);margin:0 10px 12px}.web-favorite{width:100%;justify-content:start;font-size:10px;color:var(--muted-foreground);padding-inline:10px;gap:10px;height:39px;font-weight:400}.web-favorite>svg:last-child:not(:first-child){margin-left:auto;width:10px;color:var(--subtle)}.web-sidebar-bottom{margin-top:auto;padding-top:10px}.web-sidebar-status{display:flex;gap:9px;border:1px solid var(--border);border-radius:6px;padding:12px 10px;margin-top:15px;color:var(--subtle)}.web-sidebar-status>svg{width:14px;flex-shrink:0}.web-sidebar-status strong{font-size:9px;font-weight:500;color:var(--muted-foreground);display:block}.web-sidebar-status span{font-size:8px;display:block;margin-top:4px}.web-compact .web-sidebar-label>span,.web-compact .web-nav-link span,.web-compact .web-favorite>span:not(.web-app-icon),.web-compact .web-favorite>svg:last-child:not(:first-child),.web-compact .web-sidebar-favorites>span,.web-compact .web-sidebar-status,.web-compact .web-brand>span,.web-compact .web-brand>small{display:none}.web-compact .web-nav-link,.web-compact .web-favorite{padding:0;justify-content:center}.web-compact .web-sidebar-label{padding:0;justify-content:center}.web-compact .web-brand{padding-left:19px}
.web-desktop{position:absolute;top:var(--web-header-height);bottom:var(--web-footer-height);left:var(--web-sidebar-width);right:0;outline:none;min-width:0}

.web-home{position:relative;display:flex;flex-direction:column;gap:24px;min-height:100%;width:100%;max-width:1570px;margin-inline:auto;padding:34px 36px 28px}
.web-welcome{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;min-width:0}
.web-welcome>div{min-width:0}.web-overline{font-size:10px;font-weight:600;letter-spacing:1.6px;color:var(--cyan)}
.web-welcome h1{font-size:32px;line-height:1.2;font-weight:600;letter-spacing:-1px;margin:11px 0 9px}
.web-welcome p{font-size:13px;line-height:1.6;color:var(--muted-foreground);max-width:520px}
.web-home-space{height:44px;flex-shrink:0;gap:9px;padding-inline:13px;background:var(--web-glass);border-color:var(--web-line);font-size:12px;border-radius:12px}
.web-home-space svg{width:16px;height:16px;color:var(--violet)}.web-home-space svg:last-child{width:13px;color:var(--muted-foreground)}
.web-home-overview,.web-home-continuity{display:grid;grid-template-columns:minmax(0,1.91fr) minmax(0,.92fr);gap:20px}
.web-home-ai,.web-home-environment,.web-recent,.web-home-activity{min-width:0;background:var(--web-glass);border:1px solid var(--web-line);border-radius:17px;backdrop-filter:blur(18px)}
.web-home-ai{display:flex;align-items:center;min-height:224px}.web-home-ai>.oi-surface{width:100%;padding:24px 27px}
.web-home-ai .oi-compact-head strong{white-space:normal;line-height:1.4}.web-home-ai .oi-foot{line-height:1.6}
.web-home-environment{padding:22px 24px;display:flex;flex-direction:column;gap:6px}
.web-home-environment h2{font-size:14px;font-weight:600}.web-home-environment>p{font-size:12px;line-height:1.5;color:var(--muted-foreground)}
.web-environment-actions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-block:10px 8px}
.web-environment-actions>*{height:auto;min-height:100px;min-width:0;display:flex;flex-direction:column;align-items:flex-start;gap:8px;white-space:normal;padding:12px 10px;border:1px solid var(--web-line);border-radius:11px;background:var(--web-soft-glass);text-align:left}
.web-environment-actions svg{width:22px;height:22px;color:var(--violet)}.web-environment-actions>*:nth-child(2) svg{color:var(--cyan)}.web-environment-actions>*:nth-child(3) svg{color:var(--mint)}
.web-environment-actions strong{font-size:12px;font-weight:500;line-height:1.4}.web-environment-actions small{font-size:11px;line-height:1.5;color:var(--muted-foreground)}
.web-environment-settings{width:100%;justify-content:space-between;height:44px;font-size:12px;color:var(--muted-foreground);border-top:1px solid var(--web-line);border-radius:0;padding:8px 0;margin-top:auto;white-space:normal}.web-environment-settings svg{width:14px;height:14px}
.web-featured{min-width:0}.web-featured>.web-panel-heading{margin-bottom:14px}.web-featured-apps{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px}
.web-featured-apps .web-app-tile{align-items:flex-start;height:111px;padding:16px 17px 11px;background:var(--web-glass);border:1px solid var(--web-line);border-radius:14px;gap:7px;text-align:left}
.web-featured-apps .web-app-icon{width:39px;height:39px;border-radius:11px}.web-featured-apps strong{font-size:12px;font-weight:500}.web-featured-apps small{font-size:11px;line-height:1.4;color:var(--muted-foreground)}
.web-recent,.web-home-activity{padding:20px 22px;min-height:180px}
