.web-navigation-content{display:flex;flex:1;flex-direction:column;min-height:0}.web-sidebar{position:absolute;left:0;top:var(--web-header-height);bottom:var(--web-footer-height);width:var(--web-sidebar-width);background:var(--web-bar);backdrop-filter:blur(22px);border-right:1px solid var(--border);padding:14px 11px;display:flex;flex-direction:column;z-index:40}.web-sidebar-label{display:flex;align-items:center;justify-content:space-between;padding-left:10px;color:var(--subtle);margin-bottom:10px}.web-sidebar-label>span{font-size:8px}.web-sidebar-label button{height:25px;width:25px}.web-sidebar-label svg{width:13px}.web-nav-link{width:100%;justify-content:start;gap:11px;font-size:11px;font-weight:400;padding:0 12px;min-height:39px;margin-bottom:4px;color:var(--muted-foreground);border:1px solid transparent}.web-nav-link.selected{background:var(--active-gradient);color:var(--foreground);border-color:var(--border);box-shadow:inset 2px 0 var(--cyan)}.web-nav-link.selected svg{color:var(--cyan)}.web-nav-link svg{width:17px;height:17px}.web-sidebar-favorites{border-top:1px solid var(--border);padding-top:17px;margin-top:17px}.web-sidebar-favorites>span{display:block;font-size:9px;color:var(--muted-foreground);margin:0 10px 12px}.web-favorite{width:100%;justify-content:start;font-size:10px;color:var(--muted-foreground);padding-inline:10px;gap:10px;height:39px;font-weight:400}.web-favorite>svg:last-child:not(:first-child){margin-left:auto;width:10px;color:var(--subtle)}.web-sidebar-bottom{margin-top:auto;padding-top:10px}.web-sidebar-status{display:flex;gap:9px;border:1px solid var(--border);border-radius:6px;padding:12px 10px;margin-top:15px;color:var(--subtle)}.web-sidebar-status>svg{width:14px;flex-shrink:0}.web-sidebar-status strong{font-size:9px;font-weight:500;color:var(--muted-foreground);display:block}.web-sidebar-status span{font-size:8px;display:block;margin-top:4px}.web-compact .web-sidebar-label>span,.web-compact .web-nav-link span,.web-compact .web-favorite>spa