.oi-demo-commands{display:flex;flex-wrap:wrap;justify-content:center;gap:6px;max-width:620px;margin-top:10px;align-items:center}.oi-demo-commands span{width:100%;font-size:11px;color:var(--subtle);margin-bottom:2px}
.oi-demo-commands button,.oi-followups button{font-size:12px;padding:6px 12px;border-radius:999px;border:1px solid var(--border);background:transparent;color:var(--muted-foreground);transition:background .2s,color .2s}
