.web-brand{display:flex;align-items:center;gap:8px;padding-left:19px;font:500 21px var(--font-display);min-width:0}.web-brand img{width:30px;height:30px;object-fit:contain;flex-shrink:0}.web-brand small{font:500 8px var(--font-sans);border:1px solid var(--border);border-radius:4px;padding:2px 4px;color:var(--muted-foreground)}.web-identity{padding:0;gap:9px;text-align:left}.web-identity>span:nth-child(2){display:flex;flex-direction:column;gap:3px}.web-identity strong{font-size:10px;font-weight:500}.web-identity small{font-size:8px;color:var(--muted-foreground)}.web-user-symbol{width:29px;height:29px;border:1px solid var(--border);background:var(--accent);border-radius:50%;display:grid;place-items:center;color:var(--cyan)}.web-identity>svg{width:11px}.web-user-symbol svg{width:16px}
