.oi-demo-commands button:hover,.oi-followups button:hover,.oi-demo-commands button:focus-visible,.oi-followups button:focus-visible{background:var(--accent);color:var(--foreground)}
.oi-processing h2{font-size:20px;font-weight:500}.oi-pending{font-size:13px;color:var(--muted-foreground);margin-top:6px}
.oi-stages{display:flex;gap:clamp(12px,4vw,40px);margin:26px 0 16px;justify-content:center;flex-wrap:wrap}.oi-stages li{display:flex;flex-direction:column;align-items:center;gap:8px;font-size:12px;color:var(--subtle)}.oi-stages li span{width:12px;height:12px;border-radius:50%;border:1px solid var(--border);transition:all .3s}.oi-stages li.done{color:var(--muted-foreground)}.oi-stages li.done span{background:var(--muted-foreground)}.oi-stages li.current{color:var(--foreground)}.oi-stages li.current span{background:var(--primary);box-shadow:0 0 12px var(--glow)}
