.st-sm{width:34px;height:34px;font-size:11px;border-radius:9px}.st-md{width:46px;height:46px;font-size:14px}.st-lg{width:84px;height:84px;font-size:26px;border-radius:20px}
.st-tone-violet{background:var(--web-violet-icon)}.st-tone-blue{background:var(--web-blue-icon)}.st-tone-cyan{background:var(--web-cyan-icon)}.st-tone-green{background:var(--web-mint-icon);color:var(--background)}
