 --web-wallpaper-overlay:linear-gradient(180deg,color-mix(in oklch,var(--background) 80%,transparent),color-mix(in oklch,var(--background) 75%,transparent) 40%,color-mix(in oklch,var(--background) 85%,transparent));
 --web-blue-icon:linear-gradient(150deg,color-mix(in oklch,var(--cyan) 65%,var(--primary)),var(--primary));
