.st-kinds{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:8px}
.st-kinds button,.st-ai-paths button{display:flex;gap:10px;align-items:center;text-align:left;background:var(--web-glass);border:1px solid var(--web-line);border-radius:10px;padding:12px;transition:border-color .2s,transform .2s}
.st-kinds button:hover,.st-ai-paths button:hover{border-color:var(--primary);transform:translateY(-1px)}
.st-kinds svg{width:22px;color:var(--cyan);flex-shrink:0}.st-kinds strong{display:block;font-size:12px}.st-kinds small{font-size:10px;color:var(--muted-foreground)}
.st-section{display:flex;flex-direction:column;gap:12px}
.st-h h2{font-size:18px;font-weight:600}.st-h h2 small{font-size:11px;color:var(--muted-foreground);font-weight:400}.st-h p{font-size:12px;color:var(--muted-foreground);margin-top:4px;line-height:1.6}
.st-h-row{display:flex;justify-content:space-between;gap:12px;align-items:end;flex-wrap:wrap}
.st-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px}
.st-card{position:relative;display:flex;flex-direction:column;gap:6px;background:var(--web-glass);border:1px solid var(--web-line);border-radius:12px;padding:14px;transition:border-color .2s,transform .2s,box-shadow .2s}
.st-card:hover{border-color:color-mix(in oklch,var(--primary) 60%,var(--web-line));transform:translateY(-2px);box-shadow:0 10px 30px -15px var(--primary)}
.st-card-hit{position:absolute;inset:0;border-radius:12px;z-index:0}.st-card-hit:focus-visible{outline:2px solid var(--ring)}
.st-card-top{display:flex;justify-content:space-between;align-items:start;margin-bottom:4px}
.st-card h3{font-size:14px;font-weight:600}.st-card p{font-size:11px;color:var(--muted-foreground);line-height:1.5;flex:1}
.st-card-foot{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:6px;position:relative;z-index:1}
.st-card-foot button{font-size:11px}
