.st-tone-amber{background:linear-gradient(145deg,var(--st-amber),color-mix(in oklch,var(--st-amber) 40%,var(--background)))}.st-tone-pink{background:linear-gradient(145deg,var(--st-pink),color-mix(in oklch,var(--st-pink) 40%,var(--background)))}
