.st-chips button{font-size:11px;padding:6px 12px;border-radius:99px;border:1px solid var(--web-line);background:var(--web-glass);color:var(--muted-foreground)}
.st-chips button[aria-pressed=true],.st-chips button[aria-selected=true]{background:var(--primary);color:var(--primary-foreground);border-color:var(--primary)}
.st-notice{display:flex;gap:8px;align-items:start;font-size:12px;line-height:1.5;padding:10px 12px;border-radius:9px;background:color-mix(in oklch,var(--cyan) 10%,transparent);border:1px solid color-mix(in oklch,var(--cyan) 30%,transparent)}
.st-notice svg{width:16px;flex-shrink:0;margin-top:1px}
.st-notice.warn,.st-op-blocked.st-notice{background:color-mix(in oklch,var(--st-warn) 10%,transparent);border-color:color-mix(in oklch,var(--st-warn) 35%,transparent)}
.st-op-failed.st-notice{background:color-mix(in oklch,var(--st-bad) 12%,transparent);border-color:color-mix(in oklch,var(--st-bad) 40%,transparent)}
.st-op-succeeded.st-notice{background:color-mix(in oklch,var(--st-ok) 10%,transparent);border-color:color-mix(in oklch,var(--st-ok) 35%,transparent)}
.st-ai-band{background:linear-gradient(135deg,color-mix(in oklch,var(--violet) 18%,transparent),color-mix(in oklch,var(--primary) 8%,transparent));border:1px solid var(--web-line);border-radius:14px;padding:18px}
.st-ai-paths{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:8px}
.st-ai-paths button{flex-direction:column;align-items:start}.st-ai-paths svg{width:24px;color:var(--violet)}.st-ai-paths strong{font-size:13px}.st-ai-paths small{font-size:11px;color:var(--muted-foreground);line-height:1.5}
.st-empty{display:flex;gap:10px;align-items:center;padding:20px;border:1px dashed var(--border);border-radius:10px;color:var(--muted-foreground);font-size:12px}.st-empty svg{width:18px}
.st-list,.st-ops{display:flex;flex-direction:column;gap:6px}
