.st-op{grid-template-columns:auto minmax(0,1fr) auto auto auto}
.st-row-name{text-align:left;min-width:0}.st-row-name strong,.st-op strong{display:block;font-size:12px}.st-row-name small,.st-op small{font-size:10px;color:var(--muted-foreground)}
.st-op>svg{width:18px}.st-op-state{font-size:10px;color:var(--muted-foreground)}
.st-ok{color:var(--st-ok)}.st-bad{color:var(--st-bad)}.st-warn{color:var(--st-warn)}
.st-table-wrap{overflow-x:auto;border:1px solid var(--web-line);border-radius:10px}
.st-table{width:100%;border-collapse:collapse;font-size:11px;min-width:640px}
