.st-detail{display:flex;flex-direction:column;gap:14px}
.st-back{display:flex;gap:6px;align-items:center;font-size:12px;color:var(--muted-foreground);align-self:start}.st-back svg{width:15px}
.st-detail-head{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:18px;align-items:center;background:var(--web-glass);border:1px solid var(--web-line);border-radius:14px;padding:18px}
