.st-block h3{font-size:13px;font-weight:600;margin-bottom:8px}.st-block ul{display:flex;flex-direction:column;gap:5px;font-size:12px;list-style:disc;padding-left:18px}.st-muted{font-size:12px;color:var(--muted-foreground)}
.st-plat{display:inline-flex;gap:6px;align-items:center}.st-plat svg{width:14px;color:var(--cyan)}
.st-compat-panel{display:flex;justify-content:space-between;gap:14px;align-items:center;flex-wrap:wrap;border-radius:12px;padding:16px;border:1px solid var(--web-line);background:linear-gradient(135deg,color-mix(in oklch,var(--violet) 14%,transparent),transparent)}
.st-compat-panel h3{font-size:14px;font-weight:600}.st-compat-panel p{font-size:12px;color:var(--muted-foreground);margin-top:4px;max-width:520px;line-height:1.5}
.st-compat{display:inline-flex;gap:6px;align-items:center;font-size:12px;font-weight:600;padding:6px 12px;border-radius:99px;border:1px solid currentColor;text-transform:capitalize}.st-compat svg{width:15px}
.st-connect{border:1px solid color-mix(in oklch,var(--primary) 50%,transparent);border-radius:12px;padding:16px;background:color-mix(in oklch,var(--primary) 8%,transparent);display:flex;flex-direction:column;gap:12px}
.st-connect header{display:flex;gap:10px}.st-connect header svg{width:22px;color:var(--primary);flex-shrink:0}.st-connect h3{font-size:14px;font-weight:600}.st-connect p{font-size:12px;color:var(--muted-foreground);margin-top:4px}
.st-connect ol{font-size:12px;list-style:decimal;padding-left:20px;display:flex;flex-direction:column;gap:4px}.st-connect>div{display:flex;gap:8px;flex-wrap:wrap}
.st-foot{display:flex;gap:6px;font-size:10px;color:var(--muted-foreground);line-height:1.6;padding-top:6px}.st-foot svg{width:13px;flex-shrink:0}
.web-page-store{overflow:auto}
@media (max-width:860px){
  .st-root{grid-template-columns:minmax(0,1fr);padding:10px;gap:10px}
  .st-nav{flex-direction:row;overflow-x:auto;position:static;padding:6px;scrollbar-width:none}
  .st-nav button{flex-shrink:0;font-size:11px;padding:8px 10px}
  .st-detail-head{grid-template-columns:auto minmax(0,1fr)}.st-detail-actions{grid-column:1/-1;justify-content:start}
  .st-lg{width:64px;height:64px;font-size:20px}.st-detail-head h1{font-size:20px}
  .st-hero{min-height:220px}.st-hero-copy{padding:20px}
  .st-op{grid-template-columns:auto minmax(0,1fr) auto}.st-op button{grid-column:2/-1;justify-self:start}
  .st-facts div{grid-template-columns:110px minmax(0,1fr)}
}

.web-navigation-chrome{display:flex;flex-direction:column;min-height:0;height:100%;gap:14px}.web-navigation-heading{display:flex;align-items:center;justify-content:space-between;gap:4px;flex-shrink:0}.web-navigation-heading .web-brand{padding:0;font-size:20px;gap:6px}.web-navigation-heading .web-brand img{width:28px;height:28px}.web-navigation-heading>button{width:36px;height:36px;flex-shrink:0;color:var(--muted-foreground)}.web-navigation-scroll{flex:1;min-height:0;overflow-y:auto;scrollbar-width:thin}.web-navigation-account{display:flex;align-items:center;gap:6px;flex-shrink:0;border-top:1px solid var(--border);padding-top:12px}.web-navigation-account>button{height:36px;min-width:36px;flex-shrink:0}.web-navigation-account .web-identity{flex:1;min-width:0;justify-content:flex-start;gap:6px}.web-navigation-account .web-identity>span:nth-child(2){min-width:0}.web-navigation-account .web-identity strong,.web-navigation-account .web-identity small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.web-compact .web-navigation-heading,.web-compact .web-navigation-account{flex-direction:column}.web-compact .web-navigation-heading .web-brand{padding:0}.web-compact .web-navigation-account .web-identity{flex:none;justify-content:center;width:36px}.web-compact .web-navigation-account .web-identity>span:nth-child(2),.web-compact .web-navigation-account .web-identity>svg{display:none}
