@import "tailwindcss" source(none);
@import "tw-animate-css";
@source "./components";
@source "./lib";
@source "../../composition/web";
@custom-variant dark (&:is(.dark *));
@theme inline {
 --font-sans: var(--ordax-font-family, 'Inter'), sans-serif; --font-display: var(--ordax-font-family, 'Inter'), sans-serif;
 --color-background:var(--background);--color-foreground:var(--foreground);--color-card:var(--card);--color-card-foreground:var(--foreground);--color-popover:var(--card);--color-popover-foreground:var(--foreground);--color-primary:var(--primary);--color-primary-foreground:var(--foreground);--color-secondary:var(--secondary);--color-secondary-foreground:var(--foreground);--color-muted:var(--secondary);--color-muted-foreground:var(--muted-foreground);--color-accent:var(--accent);--color-accent-foreground:var(--foreground);--color-border:var(--border);--color-input:var(--border);--color-ring:var(--primary);--color-destructive:var(--destructive);--color-destructive-foreground:var(--foreground);--color-cyan:var(--cyan);--color-violet:var(--violet);--color-mint:var(--mint);--radius-sm:4px;--radius-md:6px;--radius-lg:8px;--radius-xl:8px;
}
:root,.dark{
 --background:oklch(.135 .022 264);--foreground:oklch(.955 .008 260);--card:oklch(.175 .031 262);--primary:oklch(.6 .23 262);--secondary:oklch(.205 .035 263);--accent:oklch(.26 .06 262);--muted-foreground:oklch(.66 .037 263);--border:oklch(.29 .047 263);--cyan:oklch(.76 .15 224);--violet:oklch(.69 .19 293);--mint:oklch(.78 .145 174);--destructive:oklch(.64 .2 23);--radius:8px;
 --sidebar:oklch(.115 .025 264);--surface-deep:oklch(.15 .028 264);--subtle:oklch(.49 .034 263);--overlay:oklch(.09 .026 264 / .85);--glow:oklch(.57 .22 265 / .2);--shadow-soft:0 8px 32px oklch(.07 .025 264 / .2);--brand-gradient:linear-gradient(110deg,oklch(.52 .26 290),var(--primary) 75%,oklch(.66 .19 243));--card-gradient:linear-gradient(125deg,oklch(.19 .037 265),oklch(.145 .027 263));--active-gradient:linear-gradient(90deg,oklch(.3 .095 266),oklch(.205 .043 266));
}
@layer base{*{border-color:var(--border)}body{margin:0;background:var(--background);color:var(--foreground);font-family:var(--font-sans);font-size:13px;letter-spacing:0}h1,h2,h3,p{margin:0}h1,h2,h3{font-family:var(--font-display)}button,a,input,select{ -webkit-tap-highlight-color:transparent}button,a{touch-action:manipulation}input,select{color:var(--foreground)}a{text-decoration:none}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--cyan);outline-offset:4px}select{border:1px solid var(--border);border-radius:6px;padding:9px 12px;background:var(--secondary)}::selection{background:var(--primary)} }
.account-app{--sidebar-width:236px;min-height:100vh}.sidebar-collapsed{--sidebar-width:76px}.topbar{height:76px;position:fixed;inset:0 0 auto;z-index:30;display:grid;grid-template-columns:var(--sidebar-width) minmax(0,1fr) auto;align-items:center;background:var(--sidebar);border-bottom:1px solid var(--border);padding-right:30px}.brand{display:flex;align-items:center;gap:10px;padding-left:24px;font-family:var(--font-display);font-size:23px;font-weight:600;white-space:nowrap}.brand img{width:39px;height:39px;object-fit:contain}.brand-os{font-weight:400;color:var(--muted-foreground)}.brand sup{font-size:8px;vertical-align:top;margin-left:3px}.topbar-center{display:flex;align-items:center;gap:18px;padding-left:31px}.workspace-label{font-size:9px;font-weight:600;letter-spacing:1.6px;color:var(--muted-foreground)}.header-divider{width:1px;height:22px;background:var(--border)}.topbar-actions{display:flex;align-items:center;gap:12px}.topbar-actions button{color:var(--muted-foreground)}.search-launch{font-size:11px;height:34px;padding:0 12px;background:var(--surface-deep);border-color:var(--border);gap:12px}.search-launch kbd{font-size:10px;border:1px solid var(--border);padding:1px 4px;margin-left:30px;border-radius:3px}.account-menu{font-size:11px;padding:0 4px;gap:9px}.mini-avatar{display:grid;place-items:center;border-radius:50%;height:30px;width:30px;background:var(--accent);border:1px solid var(--border);color:var(--cyan)}.topbar .mini-avatar svg{width:17px}.desktop-sidebar{width:var(--sidebar-width);position:fixed;top:76px;bottom:0;left:0;border-right:1px solid var(--border);background:var(--sidebar);display:flex;flex-direction:column;padding:23px 15px 16px;z-index:20;transition:width .2s}.sidebar-heading{display:flex;align-items:center;justify-content:space-between;padding-left:12px;margin-bottom:12px}.sidebar-heading>span{font-size:9px;letter-spacing:1.8px;font-weight:600;color:var(--subtle)}.sidebar-heading button{color:var(--subtle);width:25px;height:25px}.sidebar