/* Public presentation uses the same token source without inheriting account layout. */
:root {
 --public-header-glass: color-mix(in oklch, var(--background) 88%, transparent);
 --public-hairline: color-mix(in oklch, var(--border) 65%, transparent);
 --public-image-shade: linear-gradient(90deg, var(--background), color-mix(in oklch, var(--background) 80%, transparent) 31%, color-mix(in oklch, var(--background) 15%, transparent) 74%), linear-gradient(0deg, var(--background), transparent 38%);
 --public-preview-glass: color-mix(in oklch, var(--surface-deep) 80%, transparent);
 --public-product-shadow: 0 28px 70px color-mix(in oklch, var(--background) 85%, transparent);
 --public-final-gradient: linear-gradient(135deg, var(--surface-deep), var(--accent));
}
.public-site {font-size:14px;line-height:1.6;overflow-x:clip;}
.public-container {width:calc(100% - 96px);max-width:1184px;margin-inline:auto;}
.public-header {position:relative;z-index:30;border-bottom:1px solid var(--public-hairline);background:var(--public-header-glass);backdrop-filter:blur(18px);}
.public-header-inner {height:86px;display:flex;align-items:center;justify-content:space-between;gap:24px;}
.public-brand {display:inline-flex;align-items:center;gap:10px;font:600 25px var(--font-display);white-space:nowrap;}
.public-brand img {object-fit:contain;}
.public-brand sup {font-size:8px;margin-left:4px;vertical-align:top;}
.public-desktop-nav {display:flex;align-items:center;gap:13px;}
.public-desktop-nav a {font-size:12px;color:var(--muted-foreground);}
.public-desktop-nav .public-nav-active,.public-mobile-menu .public-nav-active {color:var(--foreground);}
.public-header-actions {display:flex;gap:8px;align-items:center;}
.public-account-link {height:40px;font-size:12px;background:var(--surface-deep);}
.public-menu-toggle {display:none;}
.public-skip {position:absolute;top:-100px;left:24px;z-index:100;padding:10px;background:var(--card);}
.public-skip:focus {top:8px;}
.public-hero {position:relative;isolation:isolate;min-height:600px;display:flex;align-items:center;overflow:hidden;}
.public-hero-image,.public-hero-shade {position:absolute;inset:0;width:100%;height:100%;z-index:-2;object-fit:cover;object-position:60% center;}
.public-hero-shade {z-index:-1;background:var(--public-image-shade);}
.public-hero-content {padding-block:57px 65px;}
.public-status {display:inline-flex;align-items:center;gap:9px;font-size:9px;font-weight:600;letter-spacing:0;color:var(--muted-foreground);}
.public-status>span {width:5px;height:5px;border-radius:50%;background:var(--cyan);box-shadow:0 0 12px var(--glow);}
.public-hero h1 {font-size:26px;font-weight:500;line-height:1.3;margin:21px 0;}
.public-hero h1>span {display:block;margin-top:15px;font-size:64px;font-weight:500;line-height:1.12;}
.public-hero p {font-size:15px;line-height:1.9;color:var(--muted-foreground);max-width:500px;}
.public-hero-actions {display:flex;flex-wrap:wrap;gap:12px;margin-top:30px;}
.public-hero-actions a,.public-page-actions a {min-height:46px;padding-inline:21px;font-size:12px;}
.public-primary-action {background:var(--brand-gradient);border:1px solid var(--primary);min-height:46px;}
.public-hero-actions a:nth-child(2) {background:var(--public-preview-glass);}
.public-hero-note {display:flex;gap:17px;font-size:10px;color:var(--foreground);margin-top:25px;}
.public-hero-note>span {color:var(--muted-foreground);}
.public-hero-caption {position:absolute;bottom:37px;right:48px;font-size:8px;color:var(--muted-foreground);}
.public-principles {min-height:90px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--public-hairline);gap:18px;}
.public-principles>span {display:flex;gap:11px;align-items:center;color:var(--muted-foreground);font-size:12px;}
.public-principles svg {width:17px;color:var(--cyan);stroke-width:1.4;}
.public-principles>span:nth-child(2) svg {color:var(--violet);}
.public-principles>span:nth-child(3) svg {color:var(--mint);}
.public-section {padding-block:80px;}
.public-kicker {display:block;font-size:9px;font-weight:600;color:var(--cyan);letter-spacing:0;}
.public-section-heading {display:flex;justify-content:space-between;align-items:end;gap:50px;margin-bottom:35px;}
.public-site h2 {font-size:38px;line-height:1.2;font-weight:500;margin-top:14px;}
.public-section-heading>p {max-width:350px;font-size:13px;line-height:1.9;color:var(--muted-foreground);padding-bottom:4px;}
.public-product-figure {margin:0;}
.public-desktop-preview {position:relative;isolation:isolate;aspect-ratio:2.05;border:1px solid var(--border);border-radius:8px;overflow:hidden;box-shadow:var(--public-product-shadow);}
.public-preview-wallpaper {position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-2;}
.public-desktop-preview:after {position:absolute;inset:0;content:'';background:color-mix(in oklch, var(--background) 25%, transparent);z-index:-1;}
.public-preview-top {display:flex;justify-content:space-between;align-items:center;height:42px;padding:0 19px;background:var(--public-preview-glass);border-bottom:1px solid var(--public-hairline);font-size:9px;}
.public-preview-top>span:first-child {display:flex;align-items:center;gap:7px;}
.public-preview-top img {width:21px;height:21px;object-fit:contain;}
.public-preview-top>span:nth-child(2) {color:var(--muted-foreground);font-size:8px;}
.public-preview-top>svg {width:13px;}
.public-preview-rail {position:absolute;left:10px;top:58px;bottom:48px;width:45px;border:1px solid var(--public-hairline);border-radius:8px;background:var(--public-preview-glass);display:flex;align-items:center;flex-direction:column;padding:11px 0;gap:25px;}
.public-preview-rail img {height:27px;width:27px;object-fit:contain;}
.public-preview-rail>svg {width:18px;height:18px;color:var(--muted-foreground);stroke-width:1.5;}
.public-preview-rail span {flex:1;}
.public-preview-center {position:absolute;left:22%;right:17%;top:25%;text-align:center;}
.public-preview-center h3 {font-weight:500;font-size:30px;margin:10px 0 23px;}
.public-preview-center .public-kicker {font-size:8px;color:var(--foreground);}
.public-preview-search {display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px 16px;background:var(--public-preview-glass);border:1px solid var(--border);border-radius:6px;backdrop-filter:blur(14px);font-size:10px;color:var(--muted-foreground);}
.public-preview-search svg {width:15px;color:var(--cyan);}
.public-preview-search span {margin-right:auto;}
.public-preview-apps {display:flex;justify-content:center;gap:28px;margin-top:25px;}
.public-preview-apps>div {display:flex;flex-direction:column;align-items:center;gap:6px;}
.public-preview-apps>div>span {display:grid;place-items:center;width:43px;height:43px;border:1px solid var(--border);border-radius:8px;background:var(--public-preview-glass);}
.public-preview-apps svg {height:22px;width:22px;stroke-width:1.5;color:var(--cyan);}
.public-preview-apps>div:nth-child(2n) svg {color:var(--violet);}
.public-preview-apps small {font-size:8px;}
.public-preview-bottom {position:absolute;bottom:0;inset-inline:0;height:34px;display:flex;gap:10px;align-items:center;padding-inline:17px;background:var(--public-preview-glass);font-size:8px;color:var(--muted-foreground);}
.public-preview-bottom svg {width:12px;}
.public-preview-bottom>span:last-child {margin-left:auto;}
.public-product-figure figcaption {display:flex;justify-content:space-between;gap:14px;align-items:center;font-size:9px;margin-top:13px;color:var(--muted-foreground);}
.public-product-figure figcaption>span:last-child {font-size:8px;}
.public-feature-grid {display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:42px;margin-top:55px;}
.public-feature-grid article>svg {width:23px;height:23px;color:var(--cyan);stroke-width:1.5;}
.public-feature-grid article:nth-child(2)>svg {color:var(--violet);}
.public-feature-grid article:nth-child(3)>svg {color:var(--mint);}
.public-feature-grid h3 {font-size:17px;font-weight:500;margin:18px 0 11px;}
.public-feature-grid p {font-size:12px;line-height:1.9;color:var(--muted-foreground);}
.public-experience-band {background:var(--surface-deep);border-block:1px solid var(--public-hairline);}
.public-text-link {font-size:12px;color:var(--muted-foreground);padding-right:0;}
.public-experience-grid {display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;}
.public-experience-card {border:1px solid var(--border);border-radius:8px;background:var(--card-gradient);padding:28px;display:flex;flex-direction:column;align-items:start;min-width:0;}
.public-experience-card-top {display:flex;justify-content:space-between;align-items:center;width:100%;margin-bottom:36px;}
.public-experience-card-top>svg {width:29px;height:29px;color:var(--cyan);stroke-width:1.2;}
.public-experience-card:nth-child(2) .public-experience-card-top>svg {color:var(--violet);}
.public-experience-card:nth-child(3) .public-experience-card-top>svg {color:var(--mint);}
.public-experience-card-top>span {font:500 12px var(--font-display);color:var(--subtle);}
.public-experience-card h3,.public-experience-card h2 {font-size:26px;font-weight:500;margin:9px 0 14px;}
.public-experience-card p {font-size:12px;line-height:1.9;color:var(--muted-foreground);margin-bottom:24px;}
.public-availability-label {font-size:8px;line-height:1.6;color:var(--muted-foreground);display:flex;align-items:center;gap:7px;}
.public-availability-label:before {content:'';width:4px;height:4px;flex-shrink:0;background:var(--subtle);border-radius:50%;}
.public-card-action {width:100%;justify-content:space-between;padding:15px 0 0;margin-top:auto;min-height:48px;font-size:10px;color:var(--foreground);}
.public-account-section {display:grid;grid-template-columns:1fr 1.15fr;gap:80px;align-items:center;padding-block:95px;border-bottom:1px solid var(--public-hairline);}
.public-account-symbol {display:grid;place-items:center;min-height:240px;}
.public-account-symbol svg {width:140px;height:140px;color:var(--cyan);stroke-width:.65;filter:drop-shadow(0 0 24px var(--glow));}
.public-account-section p {font-size:13px;color:var(--muted-foreground);line-height:1.9;max-width:450px;margin:20px 0 25px;}
.public-account-section a {font-size:12px;height:46px;}
.public-account-section small {display:block;font-size:9px;color:var(--subtle);margin-top:13px;}
.public-faq-section {display:grid;grid-template-columns:1fr 1.6fr;gap:80px;padding-block:85px;}
.public-faq-section p {font-size:12px;color:var(--muted-foreground);margin-top:20px;}
.public-faq-section [data-slot],.public-faq-section [data-state] {min-width:0;}
.public-faq-section button {font-size:13px;line-height:1.7;gap:24px;min-height:62px;}
.public-faq-section [role=region] {font-size:12px;line-height:1.9;color:var(--muted-foreground);}
.public-final-section {text-align:center;background:var(--public-final-gradient);border-block:1px solid var(--public-hairline);padding-block:65px;}
.public-final-section h2 {font-size:42px;margin:20px 0 29px;}
.public-final-section a {font-size:12px;}
.public-final-section p {font-size:10px;color:var(--muted-foreground);margin-top:15px;}
.public-footer {padding-top:50px;}
.public-footer-top {display:flex;justify-content:space-between;gap:50px;padding-bottom:40px;}
.public-footer-top p {font-size:11px;color:var(--muted-foreground);margin-top:17px;line-height:1.9;}
.public-footer-links {display:flex;gap:100px;}
