.oi-center h1{font-size:clamp(28px,4vw,40px);font-weight:600;letter-spacing:-.01em}.oi-center h1 span{background:linear-gradient(90deg,var(--cyan),var(--primary));-webkit-background-clip:text;background-clip:text;color:transparent}
