/* OrdaX Store (namespaced .st-*) */
:root{--st-amber:oklch(0.78 0.15 70);--st-pink:oklch(0.68 0.2 350);--st-ok:var(--mint);--st-bad:oklch(0.66 0.21 25);--st-warn:var(--st-amber)}
.st-root{display:grid;grid-template-columns:200px minmax(0,1fr);gap:16px;min-height:100%;padding:14px;color:var(--foreground)}
.st-nav{display:flex;flex-direction:column;gap:2px;position:sticky;top:0;align-self:start;background:var(--web-glass);border:1px solid var(--web-line);border-radius:10px;padding:8px;backdrop-filter:blur(18px)}
.st-nav button{display:flex;align-items:center;gap:10px;padding:9px 10px;border-radius:7px;font-size:12px;color:var(--muted-foreground);text-align:left;transition:background .2s,color .2s}
.st-nav button svg{width:16px;height:16px;flex-shrink:0}.st-nav button span{flex:1;min-width:0}
.st-nav button:hover{background:var(--secondary);color:var(--foreground)}
.st-nav button[aria-current=page]{background:var(--primary);color:var(--primary-foreground)}
.st-nav b{font-size:10px;background:var(--primary);color:var(--primary-foreground);border-radius:99px;padding:1px 7px}
.st-nav button[aria-current=page] b{background:var(--background);color:var(--foreground)}
.st-main{min-width:0;display:flex;flex-direction:column;gap:14px}
.st-mode{display:flex;align-items:center;gap:14px;flex-wrap:wrap;padding:14px;background:var(--web-glass);border:1px solid var(--web-line);border-radius:10px}
.st-mode>div{flex:1;min-width:min(210px,100%)}.st-mode strong{font-size:13px}.st-mode p{font-size:12px;line-height:1.5;color:var(--muted-foreground);margin-top:4px}.st-mode button{max-width:100%;white-space:normal}
.st-searchbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.st-searchbar label{flex:1;min-width:200px;display:flex;align-items:center;gap:8px;background:var(--web-glass);border:1px solid var(--web-line);border-radius:9px;padding:0 12px;height:40px}
.st-searchbar label svg{width:16px;color:var(--muted-foreground)}.st-searchbar input{flex:1;min-width:0;background:transparent;outline:none;font-size:13px}
.st-searchbar select{height:40px;border-radius:9px;background:var(--web-glass);border:1px solid var(--web-line);padding:0 10px;font-size:12px;color:var(--foreground)}
.st-running{display:flex;gap:6px;align-items:center;font-size:11px;color:var(--cyan)}.st-running svg{width:14px}
.st-body{display:flex;flex-direction:column;gap:18px;animation:st-in .35s ease}
@keyframes st-in{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.st-body{animation:none}}
.st-hero{position:relative;border-radius:14px;overflow:hidden;border:1px solid var(--web-line);min-height:260px;display:flex;align-items:center}
.st-hero img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:right center}
.st-hero::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,var(--background) 0%,color-mix(in oklch,var(--background) 60%,transparent) 45%,transparent 75%)}
.st-hero-copy{position:relative;z-index:1;padding:32px;max-width:520px}
