.st-k-connector,.st-k-plugin{border-color:color-mix(in oklch,var(--cyan) 60%,transparent);color:var(--cyan)}
.st-k-package{border-color:color-mix(in oklch,var(--st-pink) 60%,transparent);color:var(--st-pink)}
