/* OrdaX Intelligence — adaptive surface */
.web-page.web-page-assistant{padding:0;background:transparent}
.oi-surface{position:relative;min-height:100%;height:100%;display:flex;flex-direction:column;overflow:hidden;color:var(--foreground);background:radial-gradient(ellipse 70% 55% at 50% 38%,color-mix(in oklab,var(--primary) 16%,transparent),transparent 70%),color-mix(in oklab,var(--surface-deep) 88%,transparent)}
.oi-atmosphere{position:absolute;inset:auto 0 0;height:40%;background:radial-gradient(ellipse 80% 100% at 50% 100%,color-mix(in oklab,var(--cyan) 10%,transparent),transparent 70%);pointer-events:none}
.oi-center{position:relative;flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;padding:32px 20px;text-align:center;overflow:auto}
.oi-orb{position:relative;width:170px;height:170px;display:grid;place-items:center;transition:transform .5s ease}
.oi-orb img{width:120px;height:120px;object-fit:contain;filter:drop-shadow(0 0 28px var(--glow));animation:oi-float 6s ease-in-out infinite}
.oi-ring{position:absolute;inset:0;border-radius:50%;border:1px solid color-mix(in oklab,var(--primary) 35%,transparent);animation:oi-pulse 4s ease-out infinite}.oi-ring.r2{animation-delay:2s}
