details.oi-demo-commands{display:block;margin-top:6px;text-align:center}details.oi-demo-commands summary{cursor:pointer;font-size:12px;color:var(--subtle);list-style:none;padding:4px 10px;border-radius:999px}details.oi-demo-commands summary:focus-visible{outline:2px solid var(--primary)}details.oi-demo-commands>div{display:flex;flex-wrap:wrap;justify-content:center;gap:6px;margin-top:10px;animation:oi-in .3s ease}
